import React, { useId } from "react";

export interface BalloonProps {
  /** Altura total, incluida la cola */
  height?: number;

  /** Color principal del globo */
  primaryColor?: string;

  /** Color secundario del degradado */
  secondaryColor?: string;

  /**
   * Color personalizado del borde.
   * Por defecto se calcula según el tema.
   */
  strokeColor?: string;

  /** Tema visual del globo */
  theme?: "light" | "dark";

  /** Opacidad de todo el SVG */
  opacity?: number;

  /** Clases CSS adicionales */
  className?: string;

  /** Variante de la forma del globo */
  variant?: "classic" | "icpc";

  /** Texto accesible */
  ariaLabel?: string;
}

const Balloon: React.FC<BalloonProps> = ({
  height = 104,
  primaryColor = "#ff6b81",
  secondaryColor = "#c44569",
  strokeColor,
  theme = "light",
  opacity = 1,
  className = "",
  variant = "icpc",
  ariaLabel = "Globo",
}) => {
  /*
   * useId puede devolver valores con ":".
   * Los eliminamos para evitar problemas al referenciar
   * gradientes y filtros mediante url(#id).
   */
  const reactId = useId();
  const id = `balloon-${reactId.replace(/:/g, "")}`;

  const width = height * (64 / 104);
  const isDark = theme === "dark";

  const resolvedStrokeColor =
    strokeColor ?? (isDark ? "#ffffff" : secondaryColor);

  const bodyStrokeOpacity = strokeColor
    ? 1
    : isDark
      ? 0.28
      : 0.9;

  const mainShineOpacity = isDark ? 0.55 : 0.78;
  const smallShineOpacity = isDark ? 0.22 : 0.38;

  const tailColor = isDark ? "#f4f6fb" : secondaryColor;
  const tailStartOpacity = isDark ? 0.82 : 0.95;
  const tailEndOpacity = isDark ? 0.35 : 0.55;

  const shadowOpacity = isDark ? 0.68 : 0.28;
  const shadowDy = isDark ? 2 : 1.5;
  const shadowDeviation = isDark ? 2.2 : 1.5;

  const balloonBody =
    variant === "classic"
      ? `
        M32 4
        C17 4 8 15 8 30
        C8 47 18.5 60 28.8 66.6
        C30.1 67.5 31.1 68.2 32 69
        C32.9 68.2 33.9 67.5 35.2 66.6
        C45.5 60 56 47 56 30
        C56 15 47 4 32 4
        Z
      `
      : `
        M32 5
        C19 5 10 16 10 31
        C10 46 18 58 28 66
        C30 67 31 68.2 32 69
        C33 68.2 34 67 36 66
        C46 58 54 46 54 31
        C54 16 45 5 32 5
        Z
      `;

  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      width={width}
      height={height}
      viewBox="0 0 64 104"
      preserveAspectRatio="xMidYMid meet"
      className={className}
      opacity={opacity}
      role="img"
      aria-label={ariaLabel}
    >
      <defs>
        {/* Degradado del cuerpo */}
        <radialGradient
          id={`${id}-body`}
          cx={isDark ? "34%" : "35%"}
          cy={isDark ? "23%" : "24%"}
          r={isDark ? "80%" : "78%"}
          fx={isDark ? "34%" : "35%"}
          fy={isDark ? "23%" : "24%"}
        >
          <stop offset="0%" stopColor={primaryColor} />

          <stop
            offset={isDark ? "58%" : "64%"}
            stopColor={primaryColor}
          />

          <stop offset="100%" stopColor={secondaryColor} />
        </radialGradient>

        {/* Brillo principal */}
        <linearGradient
          id={`${id}-shine`}
          x1="0"
          y1="0"
          x2="1"
          y2="1"
        >
          <stop
            offset="0%"
            stopColor="#ffffff"
            stopOpacity={mainShineOpacity}
          />

          <stop
            offset="100%"
            stopColor="#ffffff"
            stopOpacity={0}
          />
        </linearGradient>

        {/* Degradado de la cola */}
        <linearGradient
          id={`${id}-tail`}
          x1="0"
          y1="73"
          x2="0"
          y2="103"
          gradientUnits="userSpaceOnUse"
        >
          <stop
            offset="0%"
            stopColor={tailColor}
            stopOpacity={tailStartOpacity}
          />

          <stop
            offset="100%"
            stopColor={tailColor}
            stopOpacity={tailEndOpacity}
          />
        </linearGradient>

        {/* Sombra */}
        <filter
          id={`${id}-shadow`}
          x="-40%"
          y="-30%"
          width="180%"
          height="185%"
        >
          <feDropShadow
            dx="0"
            dy={shadowDy}
            stdDeviation={shadowDeviation}
            floodColor="#000000"
            floodOpacity={shadowOpacity}
          />
        </filter>
      </defs>

      {/* Cuerpo */}
      <path
        d={balloonBody}
        fill={`url(#${id}-body)`}
        stroke={resolvedStrokeColor}
        strokeWidth={isDark ? 1.5 : 1.7}
        strokeOpacity={bodyStrokeOpacity}
        strokeLinejoin="round"
        filter={`url(#${id}-shadow)`}
      />

      {/* Brillo lateral */}
      <path
        d="
          M19.7 17.8
          C16.7 23.4 17.9 35.9 24.8 43
          C29.5 37.5 30.8 27.5 27.8 20.2
          C26.6 17.2 23.5 16 19.7 17.8
          Z
        "
        fill={`url(#${id}-shine)`}
      />

      {/* Reflejo pequeño */}
      <ellipse
        cx="25"
        cy="15.8"
        rx="4"
        ry="2.4"
        fill="#ffffff"
        opacity={smallShineOpacity}
        transform="rotate(-12 25 15.8)"
      />

      {/* Nudo */}
      <path
        d="
          M29.3 68.3
          Q32 70.1 34.7 68.3
          L35.3 72.8
          Q32 74.5 28.7 72.8
          Z
        "
        fill={secondaryColor}
        stroke={isDark ? "#ffffff" : secondaryColor}
        strokeWidth={0.8}
        strokeOpacity={isDark ? 0.24 : 1}
        strokeLinejoin="round"
      />

      {/* Cola curva */}
      <path
        d="
          M32 73.7
          C31.2 78.3 37.2 80.1 35.3 84.8
          C33.5 89.3 26.4 89.8 28.1 94.5
          C29.5 98.3 35.9 97.1 37.1 102
        "
        fill="none"
        stroke={`url(#${id}-tail)`}
        strokeWidth={1.45}
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
};

export default Balloon;

