import React from "react";
import BearGlyph, { BearGlyphProps } from "./BearGlyph";

export type LogoVariant = "stacked" | "horizontal" | "mark";

export interface UPDSJudgeLogoProps extends Omit<BearGlyphProps, "width" | "height"> {
  width?: number | string;
  height?: number | string;
  /** 'light' (por defecto) u 'oscuro'. Cambia el texto y el color de ojos/nariz/boca. */
  theme?: "light" | "dark";
  /** Color de "UPDS" (si no se pasa, se calcula según theme) */
  textColorPrimary?: string;
  /** Color de "Judge" (si no se pasa, se calcula según theme) */
  textColorAccent?: string;
  variant?: LogoVariant;
  className?: string;
}

/**
 * Logo completo de UPDSJudge (oso + wordmark).
 * Un solo componente: los colores cambian por props, no hay dos SVG separados.
 */
const UPDSJudgeLogo: React.FC<UPDSJudgeLogoProps> = ({
  width = 200,
  height,
  theme = "light",
  detailColor,
  contourColor,
  textColorPrimary,
  textColorAccent,
  variant = "stacked",
  className,
  ...glyphProps
}) => {
  const resolvedDetail = detailColor ?? (theme === "dark" ? "#0A0D14" : "#15253C");
  const resolvedContour = contourColor ?? (theme === "dark" ? "#FFFFFF" : "#15253C");
  const resolvedTextPrimary =
    textColorPrimary ?? (theme === "dark" ? "#FFFFFF" : "#15253C");
  const resolvedTextAccent =
    textColorAccent ?? (theme === "dark" ? "#FFFFFF" : "#215F63");

  if (variant === "mark") {
    return (
      <BearGlyph
        width={width}
        height={height}
        detailColor={resolvedDetail}
        contourColor={resolvedContour}
        className={className}
        {...glyphProps}
      />
    );
  }

  const isHorizontal = variant === "horizontal";
  const w = typeof width === "number" ? width : 200;
  const h = height ?? (isHorizontal ? w * 0.32 : w * 1.15);

  return (
    <svg
      width={w}
      height={h}
      viewBox={isHorizontal ? "0 0 900 260" : "0 0 851 750"}
      xmlns="http://www.w3.org/2000/svg"
      className={className}
      role="img"
      aria-label="UPDSJudge"
    >
      <g transform={isHorizontal ? "translate(0, -170) scale(0.85)" : "translate(0,0)"}>
        <BearGlyph
          width={450}
          height={380}
          detailColor={resolvedDetail}
          contourColor={resolvedContour}
          {...glyphProps}
        />
      </g>
      <g transform={isHorizontal ? "translate(430, 40)" : "translate(0, 0)"}>
        <text
          x={isHorizontal ? 0 : 122}
          y={isHorizontal ? 130 : 640.735}
          fontFamily="'Poppins', 'Segoe UI', sans-serif"
          fontWeight={700}
          fontSize={isHorizontal ? 90 : 75}
        >
          <tspan fill={resolvedTextPrimary}>UPDS</tspan>
          <tspan fill={resolvedTextAccent}>Judge</tspan>
        </text>
      </g>
    </svg>
  );
};

export default UPDSJudgeLogo;

