export function AppLogo({
  alt = 'UPDS Judge',
  className,
  size = 'md',
  variant = 'default',
  ...props
}: AppLogoProps) {
  const sizes = { sm: 'h-7 w-auto', md: 'h-10 w-auto', lg: 'h-14 w-auto' }

  return (
    <img
      src={variant === 'dark' ? logoDark : logo}
      alt={alt}
      className={cn(sizes[size], className)}
      {...props}
