import balloon from '@/assets/components/Balloon/balloon.svg'
import { cn } from '@/lib/utils/cn'

type GlobeIllustrationProps = {
  className?: string
  decorative?: boolean
  label?: string
  size?: number | string
}

export function GlobeIllustration({
  className,
  decorative = true,
  label = 'Globo de programación competitiva',
  size = 104,
}: GlobeIllustrationProps) {
  return (
    <img
      src={balloon}
