import type { PropsWithChildren } from 'react'
import { NavLink, useLocation } from 'react-router-dom'
import { AppLogo } from '@/components/branding/AppLogo'
import { UserMenu } from '@/components/navigation/UserMenu'
import { deriveIdentity } from '@/lib/auth/identity'
import { cn } from '@/lib/utils/cn'
import { routes } from '@/routes/constants'

const userNavigation = [{ label: 'Inicio', path: routes.studentHome }]

export function UserLayout({ children }: PropsWithChildren) {
  const identity = deriveIdentity(sessionStorage.getItem('token'))
  const location = useLocation()

  return (
    <div className="min-h-screen bg-[var(--background)]">
      <header className="border-b border-[var(--border)] bg-white">
        <div className="mx-auto flex min-h-16 max-w-6xl items-center justify-between gap-4 px-5">
          <AppLogo alt="UPDS Judge" />
          <nav aria-label="Navegación de usuario" className="min-w-0 overflow-x-auto">
            <ul className="flex items-center gap-2 whitespace-nowrap">
              {userNavigation.map((item) => {
                const active = location.pathname === item.path
                return (
                  <li key={item.path}>
                    <NavLink
                      to={item.path}
                      aria-current={active ? 'page' : undefined}
                      className={cn(
                        'rounded-md px-3 py-2 text-sm font-semibold focus-visible:outline-2 focus-visible:outline-[var(--focus)]',
                        active
                          ? 'bg-[var(--surface-muted)] text-[var(--text-primary)]'
                          : 'text-[var(--text-secondary)] hover:text-[var(--text-primary)]',
                      )}
                    >
                      {item.label}
                    </NavLink>
                  </li>
                )
              })}
            </ul>
          </nav>
          <div className="flex min-w-0 items-center gap-3">
            <div className="hidden min-w-0 text-right sm:block">
              <p className="truncate text-sm font-semibold">
                {identity?.name || identity?.email || 'Usuario'}
              </p>
              <p className="text-xs text-[var(--text-secondary)]">Usuario</p>
            </div>
            <UserMenu identity={identity} />
          </div>
        </div>
      </header>
      <main className="mx-auto max-w-6xl p-5">{children}</main>
    </div>
  )
}

import type { ContestProblemForm, FiltroEstadoConcurso } from './types'

export const MAX_CONTEST_ZIP_SIZE_BYTES = 100 * 1024 * 1024
export const MAX_CONTEST_PROBLEMS = 12

export const CONTEST_CODE_CHARACTER_CATEGORIES = {
  lowercaseLetters: 'a-z',
  digits: '0-9',
  separator: '-',
} as const
export const CONTEST_CODE_PATTERN = /^[a-z0-9]+(?:-[a-z0-9]+)*$/
export const CONTEST_CODE_ERROR =
  'El código debe usar letras minúsculas, números y guiones simples.'
export const CONTEST_CODE_HINT =
  'Usá letras minúsculas, números y guiones simples (ej.: regional-2026).'

export const ADMIN_CONTEST_FILTERS: readonly {
  label: string
  value: FiltroEstadoConcurso
}[] = [
  { label: 'Todos', value: 'todos' },
  { label: 'Activos', value: 'activos' },
  { label: 'Pendientes', value: 'proximos' },
  { label: 'Finalizados', value: 'finalizados' },
]

export const newContestProblem = (): ContestProblemForm => ({
  titulo: '',
  tiempo: 1,
  memoria: 256,
})

export const normalizeContestPassword = (
  value: string | null | undefined,
): string => (typeof value === 'string' ? value.trim() : '')

export const normalizeContestCode = (
  value: string | null | undefined,
): string => (typeof value === 'string' ? value.trim().toLowerCase() : '')

export const getContestZipError = (file?: File) => {
  if (!file) return undefined
  if (!file.name.toLowerCase().endsWith('.zip')) {
    return 'El archivo debe tener extensión .zip.'
  }
  if (file.size > MAX_CONTEST_ZIP_SIZE_BYTES) {
    return 'El ZIP no puede superar 100 MB.'
  }
  return undefined
}

import { endpoints, httpClient } from '@/lib/api'
import { createContestFormData } from './mapper'
import type {
  ConcursosAdminResumen,
  CreateContestFormValues,
  CreateContestResponse,
  ListConcursosParams,
  ListConcursosResponse,
} from './types'

export const createContest = (values: CreateContestFormValues) =>
  httpClient.post<CreateContestResponse>(
    endpoints.contests.create,
    createContestFormData(values),
  )

export const listConcursos = (params: ListConcursosParams) => {
  const query = new URLSearchParams()

  for (const [key, value] of Object.entries(params)) {
    if (value !== undefined && value !== '') query.set(key, String(value))
  }

  return httpClient.get<ListConcursosResponse>(
    `${endpoints.contests.adminList}?${query.toString()}`,
  )
}

export const getConcursosAdminResumen = () =>
  httpClient.get<ConcursosAdminResumen>(endpoints.contests.adminSummary)

/** Relative to the configured /api base URL. */
export const endpoints = {
  auth: {
    login: 'Auth/login',
    register: 'Auth/register',
  },
  contests: {
    adminList: 'Concursos/mis-creados',
    adminSummary: 'Concursos/mis-resumen',
    create: 'Concursos/crear',
  },
} as const

import { useQuery } from '@tanstack/react-query'
import { useEffect, useState } from 'react'
import { getConcursosAdminResumen, listConcursos } from './service'
import type { ListConcursosParams } from './types'

export const concursosKeys = {
  all: ['concursos'] as const,
  adminList: (params: ListConcursosParams) =>
    [
      'concursos',
      'admin-list',
      params.filtro,
      params.modalidad,
      params.busqueda,
      params.pagina,
      params.tamanoPagina,
    ] as const,
  adminSummary: () => ['concursos', 'admin-summary'] as const,
}

export function useConcursosList(params: ListConcursosParams) {
  return useQuery({
    queryKey: concursosKeys.adminList(params),
    queryFn: () => listConcursos(params),
    placeholderData: (previous) => previous,
  })
}

export function useConcursosAdminResumen() {
  return useQuery({
    queryKey: concursosKeys.adminSummary(),
    queryFn: getConcursosAdminResumen,
    staleTime: 5 * 60 * 1000,
    refetchOnWindowFocus: false,
    refetchOnReconnect: false,
  })
}

export function useDebouncedValue<T>(value: T, delayMs = 350) {
  const [debounced, setDebounced] = useState(value)

  useEffect(() => {
    const timeout = window.setTimeout(() => setDebounced(value), delayMs)
    return () => window.clearTimeout(timeout)
  }, [value, delayMs])

  return debounced
}

import { Button } from '@/components/common'
import { SearchInput, Select } from '@/components/forms'
import { ADMIN_CONTEST_FILTERS } from '../constants'
import type { FiltroEstadoConcurso } from '../types'

export type ContestsFiltersValue = {
  busqueda: string
  filtro: FiltroEstadoConcurso
}

export function ContestsFiltersBar({
  value,
  onChange,
  onClear,
}: {
  value: ContestsFiltersValue
  onChange: (next: ContestsFiltersValue) => void
  onClear: () => void
}) {
  return (
    <div className="flex flex-wrap items-center gap-4">
      <SearchInput
        className="min-w-2xs flex-1"
        aria-label="Buscar concursos por código"
        placeholder="Buscar concurso..."
        value={value.busqueda}
        onChange={(event) => onChange({ ...value, busqueda: event.target.value })}
      />

      <Select
        className="flex min-w-[150px]"
        aria-label="Filtrar por estado"
        value={value.filtro}
        onChange={(event) =>
          onChange({
            ...value,
            filtro: event.target.value as FiltroEstadoConcurso,
          })
        }
      >
        {ADMIN_CONTEST_FILTERS.map((filter) => (
          <option key={filter.value} value={filter.value}>
            {filter.label}
          </option>
        ))}
      </Select>

      <Button
        type="button"
        variant="secondary"
        className="min-w-15"
        onClick={onClear}
      >
        Limpiar
      </Button>
    </div>
  )
}

import { Alert } from '@/components/common'
import { StatCard } from '@/components/navigation'
import type { ConcursosAdminResumen } from '../types'

export function ContestsSummaryCards({
  resumen,
  error,
  isLoading = false,
  isRefreshing = false,
}: {
  resumen?: ConcursosAdminResumen
  error?: string
  isLoading?: boolean
  isRefreshing?: boolean
}) {
  if (error && !resumen) return <Alert tone="danger">{error}</Alert>

  const cards = [
    { key: 'activos', label: 'Activos', value: resumen?.activos, tone: 'success' as const },
    { key: 'proximos', label: 'Pendientes', value: resumen?.proximos, tone: 'neutral' as const },
    {
      key: 'finalizados',
      label: 'Finalizados',
      value: resumen?.finalizados,
      tone: 'neutral' as const,
    },
  ]

  return (
    <section aria-label="Resumen de concursos" className="space-y-2">
      {error && <Alert tone="danger">{error}</Alert>}
      <div className="grid w-full grid-cols-1 gap-4 md:grid-cols-3">
        {cards.map((card) => (
          <StatCard
            key={card.key}
            label={card.label}
            value={isLoading && !resumen ? '—' : (card.value ?? '—')}
            tone={card.tone}
          />
        ))}
      </div>
      {isRefreshing && resumen && (
        <p role="status" className="text-sm text-[var(--text-secondary)]">
          Actualizando resumen…
        </p>
      )}
    </section>
  )
}

import { useMemo, useState } from 'react'
import { Alert, Button, Card, LinkButton } from '@/components/common'
import { Pagination } from '@/components/navigation'
import { ApiError } from '@/lib/api'
import { routes } from '@/routes/constants'
import {
  ContestsFiltersBar,
  type ContestsFiltersValue,
} from './components/ContestsFiltersBar'
import { ContestsAdminTable } from './components/ContestsAdminTable'
import { ContestsSummaryCards } from './components/ContestsSummaryCards'
import {
  useConcursosAdminResumen,
  useConcursosList,
  useDebouncedValue,
} from './hooks'
import type { ListConcursosParams } from './types'

const PAGE_SIZE = 10

const initialFilters: ContestsFiltersValue = {
  busqueda: '',
  filtro: 'todos',
}

const errorMessage = (error: unknown) =>
  error instanceof ApiError
    ? error.message
    : 'No se pudieron cargar los concursos. Intentá de nuevo.'

export function ContestsAdminScreen() {
  const [filters, setFilters] = useState(initialFilters)
  const [page, setPage] = useState(1)
  const debouncedBusqueda = useDebouncedValue(filters.busqueda)

  const queryParams: ListConcursosParams = useMemo(
    () => ({
      filtro: filters.filtro,
      busqueda: debouncedBusqueda || undefined,
      pagina: page,
      tamanoPagina: PAGE_SIZE,
    }),
    [filters.filtro, debouncedBusqueda, page],
  )

  const list = useConcursosList(queryParams)
  const summary = useConcursosAdminResumen()
  const refreshing = list.isFetching || summary.isFetching
  const totalPages = list.data
    ? Math.max(1, Math.ceil(list.data.total / list.data.tamanoPagina))
    : 1

  const updateFilters = (next: ContestsFiltersValue) => {
    setFilters(next)
    setPage(1)
  }

  const refreshAll = async () => {
    if (refreshing) return
    await Promise.all([list.refetch(), summary.refetch()])
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div>
          <h1 className="text-2xl font-bold">Administración de concursos</h1>
          <p className="text-sm text-[var(--text-secondary)]">
            Crea y gestiona tus concursos.
          </p>
        </div>
        <LinkButton href={routes.newContest} variant="primary">
          Nuevo concurso
        </LinkButton>
      </div>

      <ContestsSummaryCards
        resumen={summary.data}
        error={summary.error ? errorMessage(summary.error) : undefined}
        isLoading={summary.isLoading}
        isRefreshing={summary.isFetching}
      />

      <Card>
        <div className="space-y-4">
          <ContestsFiltersBar
            value={filters}
            onChange={updateFilters}
            onClear={() => updateFilters(initialFilters)}
          />

          {list.error ? (
            <Alert tone="danger">
              {errorMessage(list.error)}{' '}
              <button
                type="button"
                className="font-semibold underline"
                onClick={() => list.refetch()}
              >
                Reintentar
              </button>
            </Alert>
          ) : (
            <>
              <ContestsAdminTable
                rows={list.data?.concursos ?? []}
                loading={list.isLoading || list.isFetching}
              />
              <div className="flex items-center justify-between">
                <p className="text-sm text-[var(--text-secondary)]">
                  {list.data ? `${list.data.total} concurso(s) encontrados` : ' '}
                </p>
                <Pagination page={page} totalPages={totalPages} onPageChange={setPage} />
              </div>
            </>
          )}
        </div>
      </Card>

      <div className="flex justify-end">
        <Button
          variant="ghost"
          onClick={refreshAll}
          disabled={refreshing}
          loading={refreshing}
          aria-label="Actualizar listado y resumen"
        >
          Actualizar
        </Button>
      </div>
    </div>
  )
}

