it('renders the existing student route inside UserLayout', async () => {
  sessionStorage.setItem(
    'token',
    'header.eyJuYW1lIjoiQWRhIiwicm9sZSI6IlVzdWFyaW8ifQ.signature',
  )
  const router = createAppRouter(false)
  await router.navigate('/student')
  render(<RouterProvider router={router} />)

  expect(await screen.findByRole('heading', { name: 'Área de usuario' })).toBeInTheDocument()
  expect(screen.getByRole('navigation', { name: 'Navegación de usuario' })).toBeInTheDocument()
  expect(screen.getByRole('button', { name: 'Abrir menú de usuario' })).toBeInTheDocument()
